package com.wizzadrds.theworldremembers.behavior; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import net.minecraft.core.BlockPos; import java.util.UUID; class NpcActivityManagerTest{@Test void prioritiesRespectInterruptibility(){assertTrue(NpcActivity.SLEEPING.interruptible()==false);assertTrue(NpcActivity.WORKING.interruptible());var s=new NpcActivityState(UUID.randomUUID(),NpcActivity.WORKING,10,true,new BlockPos(1,2,3),4);assertEquals(10,s.priority());}}